/**
 * A screen the board writes survives the deploy that follows it.
 *
 * `Screens/quicknew.txt` is generated by QuickNew at every logoff AND tracked in
 * git, and `Screens` is one of the blanket `tar` sync directories, so every
 * deploy copied the image's committed copy over the board's own output.
 *
 * Watched three times on 2026-09-15 while the sysop was testing the restored
 * 68K door: the generator wrote 3079 bytes at 09:21, the next deploy put 3166
 * bytes from 05:35 back, and the sysop spent twenty minutes reading a stale
 * screen and reasonably believing it was the door's work. Third instance of the
 * same bug in this entrypoint - Access/*.info and the nine 68K door state files
 * were the first two.
 *
 * ONE LIST, TWO READERS. `screens/board-written-screens.json` is the single copy;
 * `screen-tables.ts` builds BOARD_WRITTEN_NAME from it and the entrypoint greps
 * it. This test drives the ENTRYPOINT'S OWN BLOCK against a staged board, so
 * what is checked is the shell that runs, not a restatement of its rule.
 */

import { execFileSync } from 'child_process';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

const REPO = path.join(__dirname, '..', '..', '..', '..');
const ENTRYPOINT = path.join(REPO, 'docker-entrypoint.sh');
const LIST = path.join(REPO, 'web', 'backend', 'src', 'screens', 'board-written-screens.json');

/** The exclude-building pass, lifted verbatim. */
function extractExcludePass(): string {
  const source = fs.readFileSync(ENTRYPOINT, 'utf8');
  const start = source.indexOf('    SCREEN_WRITTEN_EXCLUDES=$(mktemp)');
  const end = source.indexOf('    for sync_dir in Doors Screens Libs C; do', start);
  if (start === -1 || end === -1) throw new Error('the board-written exclude pass was not found');
  return source.slice(start, end);
}

function stage(): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'gen-screens-'));
  for (const side of ['image', 'volume']) {
    fs.mkdirSync(path.join(root, side, 'Screens'), { recursive: true });
  }
  return root;
}

const write = (root: string, side: string, name: string, body: string) =>
  fs.writeFileSync(path.join(root, side, 'Screens', name), body);

const read = (root: string, side: string, name: string) =>
  fs.readFileSync(path.join(root, side, 'Screens', name), 'utf8');

/** Build the excludes the way the entrypoint does, then run the same tar. */
function runDeploy(root: string): string {
  const script = [
    'set -e',
    'DEFAULT_DATA_DIR="$1"',
    'BBS_DATA_DIR="$2"',
    extractExcludePass(),
    '(cd "$DEFAULT_DATA_DIR/Screens" && tar cf - --exclude-from="$SCREEN_WRITTEN_EXCLUDES" .) | (cd "$BBS_DATA_DIR/Screens" && tar xf -)',
  ].join('\n');

  return execFileSync('sh', ['-c', script, 'entrypoint', path.join(root, 'image'), path.join(root, 'volume')], {
    encoding: 'utf8',
    env: { ...process.env, BOARD_WRITTEN_LIST: LIST },
  });
}

describe('generated screens across a deploy', () => {
  let root: string;

  beforeEach(() => { root = stage(); });
  afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

  it('keeps the new-files screen the door just generated', () => {
    write(root, 'image', 'quicknew.txt', 'the committed sample');
    write(root, 'volume', 'quicknew.txt', 'what QuickNew wrote at logoff');

    runDeploy(root);

    expect(read(root, 'volume', 'quicknew.txt')).toBe('what QuickNew wrote at logoff');
  });

  it('keeps the achievements leaderboard and the last-caller screen', () => {
    for (const name of ['achievetop.txt', 'lastc.txt']) {
      write(root, 'image', name, 'sample');
      write(root, 'volume', name, `live ${name}`);
    }

    runDeploy(root);

    for (const name of ['achievetop.txt', 'lastc.txt']) {
      expect(read(root, 'volume', name)).toBe(`live ${name}`);
    }
  });

  it('keeps the requests bulletin, which a door writes', () => {
    write(root, 'image', 'bull9.txt', 'sample');
    write(root, 'volume', 'bull9.txt', 'the requests a caller added');

    runDeploy(root);

    expect(read(root, 'volume', 'bull9.txt')).toBe('the requests a caller added');
  });

  it('keeps logs, which were never art', () => {
    write(root, 'image', 'door.log', 'sample');
    write(root, 'volume', 'door.log', 'what actually happened');

    runDeploy(root);

    expect(read(root, 'volume', 'door.log')).toBe('what actually happened');
  });

  it('STILL updates the art, which is the image to give', () => {
    // The exclusion has to be surgical. A deploy that stopped shipping the
    // sysop's screens would be a worse bug than the one being fixed.
    write(root, 'image', 'BBSTITLE.txt', 'the new logo');
    write(root, 'volume', 'BBSTITLE.txt', 'the old logo');

    runDeploy(root);

    expect(read(root, 'volume', 'BBSTITLE.txt')).toBe('the new logo');
  });

  it('seeds a generated screen on a board that has none', () => {
    write(root, 'image', 'quicknew.txt', 'the committed sample');

    runDeploy(root);
    // The tar holds it back; the seeding pass beside it is what puts a first
    // copy on a fresh board, so after the sync alone it is simply absent.
    expect(fs.existsSync(path.join(root, 'volume', 'Screens', 'quicknew.txt'))).toBe(false);
  });

  it('reads the shared list rather than a copy of it', () => {
    // The count the shell reports must match the file, so an edit that stops
    // reading it fails here instead of silently falling back.
    const out = runDeploy(root);
    const patterns = Object.keys(JSON.parse(fs.readFileSync(LIST, 'utf8')))
      .filter(k => k !== '_comment');

    expect(out).toContain(`${patterns.length} pattern(s) held back`);
  });

  it('is the same file the TypeScript table reads', () => {
    // JSON because the third reader is a browser: web/config-app aliases
    // @bbs/screens at the backend source, so screen-tables.ts is bundled by
    // vite and has no filesystem. Parsing here is the cheap proof that the
    // shell and the bundle are looking at one document.
    const parsed = JSON.parse(fs.readFileSync(LIST, 'utf8'));
    const patterns = Object.keys(parsed).filter(k => k !== '_comment');

    expect(patterns).toContain('quicknew\\.txt');
    // Every pattern carries its reason beside it, not in a comment above it.
    for (const p of patterns) expect(typeof parsed[p]).toBe('string');
    // And every one compiles as the regex the table will build.
    for (const p of patterns) expect(() => new RegExp(`^(${p})$`, 'i')).not.toThrow();
  });
});
